import{_ as e,o as d,c as i,an as r}from"./chunks/framework.acQJJyLm.js";const y=JSON.parse('{"title":"Concepts: operators and the pieces they compose","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/concepts.md","filePath":"getting-started/concepts.md","lastUpdated":null}'),a={name:"getting-started/concepts.md"};function o(l,t,n,s,g,h){return d(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="concepts" tabindex="-1">Concepts: operators and the pieces they compose <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts: operators and the pieces they compose {#concepts}&quot;">​</a></h1><p>An operator is a recurrence or a convolution built from a kernel and the pieces that shape its steps. Find the piece you need by intent here, then see it at work in the tutorials.</p><p>Names that are public but not exported are written unqualified below. Load them with <code>using ComposableRecurrences: Depletion, Floor, with_state</code>, and so on.</p><p>The package has these layers.</p><ul><li><p><strong>Operators</strong> step a series forward or weight past inputs.</p></li><li><p><strong>Calls and state</strong> run an operator over a window of time and resume it.</p></li><li><p><strong>Shapes</strong> mark how a kernel, coupling or parameter is indexed by strata and time.</p></li><li><p><strong>Couplings</strong> mix strata within a step.</p></li><li><p><strong>Modifiers</strong> act on each step&#39;s values in order.</p></li><li><p><strong>Variants</strong> choose between forms of one piece.</p></li><li><p><strong>Extending</strong> adds your own piece.</p></li><li><p><strong>Tooling</strong> checks an operator&#39;s gradients.</p></li></ul><h2 id="Operators" tabindex="-1">Operators <a class="header-anchor" href="#Operators" aria-label="Permalink to &quot;Operators {#Operators}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Name</th><th style="text-align:right;">What it does</th><th style="text-align:right;">Returns</th></tr></thead><tbody><tr><td style="text-align:right;"><code>Recurrence(kernel; coupling, modifiers)</code></td><td style="text-align:right;">steps a series forward from its own last <code>L</code> values; kernel lag 1 first</td><td style="text-align:right;">a callable operator</td></tr><tr><td style="text-align:right;"><code>Convolution(kernel)</code></td><td style="text-align:right;">weights current and past inputs by a kernel; kernel lag 0 first</td><td style="text-align:right;">a callable operator</td></tr></tbody></table><h2 id="Calls-and-state" tabindex="-1">Calls and state <a class="header-anchor" href="#Calls-and-state" aria-label="Permalink to &quot;Calls and state {#Calls-and-state}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Name</th><th style="text-align:right;">What it does</th><th style="text-align:right;">Returns</th></tr></thead><tbody><tr><td style="text-align:right;"><code>r(gain; history, add, start, stop)</code></td><td style="text-align:right;">runs a recurrence over <code>start:stop</code>; <code>gain</code> scales and <code>add</code> adds before the modifiers</td><td style="text-align:right;">length <code>T</code> or <code>S × T</code> output</td></tr><tr><td style="text-align:right;"><code>c(x; history, start, stop)</code></td><td style="text-align:right;">runs a convolution over <code>start:stop</code></td><td style="text-align:right;">output in the layout of <code>x</code></td></tr><tr><td style="text-align:right;"><code>with_state(op, args...; kwargs...)</code></td><td style="text-align:right;">the same call, also returning where it stopped</td><td style="text-align:right;"><code>(y, state)</code></td></tr><tr><td style="text-align:right;"><code>r(...; state)</code></td><td style="text-align:right;">resumes from a <code>State</code>, for example a forecast after a fit</td><td style="text-align:right;">output from <code>state.t</code> on</td></tr><tr><td style="text-align:right;"><code>seeded(r, gain; history)</code></td><td style="text-align:right;">runs after the seed days and returns them joined</td><td style="text-align:right;">seed and output</td></tr><tr><td style="text-align:right;"><code>State</code></td><td style="text-align:right;">the last outputs, each modifier&#39;s state and the next time</td><td style="text-align:right;">a struct</td></tr></tbody></table><h2 id="Shapes" tabindex="-1">Shapes <a class="header-anchor" href="#Shapes" aria-label="Permalink to &quot;Shapes {#Shapes}&quot;">​</a></h2><p>A bare array has the slot&#39;s own axes only. Data (inputs, history and outputs) are strata × time and are never wrapped.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Name</th><th style="text-align:right;">What it does</th><th style="text-align:right;">Returns</th></tr></thead><tbody><tr><td style="text-align:right;">vector</td><td style="text-align:right;">one kernel shared by every stratum</td><td style="text-align:right;"><code>L</code> lags</td></tr><tr><td style="text-align:right;"><code>PerStratum(x)</code></td><td style="text-align:right;">one kernel or parameter per stratum</td><td style="text-align:right;">adds a leading <code>S</code> axis</td></tr><tr><td style="text-align:right;"><code>Pairwise(A)</code></td><td style="text-align:right;">one kernel per pair of strata, which mixes strata itself so the coupling stays <code>I</code></td><td style="text-align:right;"><code>S × S × L</code></td></tr><tr><td style="text-align:right;"><code>TimeVarying(x)</code></td><td style="text-align:right;">a kernel, coupling or parameter that changes by day</td><td style="text-align:right;">adds a trailing <code>T</code> axis</td></tr><tr><td style="text-align:right;"><code>Secondary()</code></td><td style="text-align:right;">column <code>t</code> is read at output time <code>t</code>; the default</td><td style="text-align:right;">an indexing variant</td></tr><tr><td style="text-align:right;"><code>Primary()</code></td><td style="text-align:right;">column <code>c</code> is the kernel of the input at time <code>c</code>; convolution kernels only</td><td style="text-align:right;">an indexing variant</td></tr></tbody></table><h2 id="Couplings" tabindex="-1">Couplings <a class="header-anchor" href="#Couplings" aria-label="Permalink to &quot;Couplings {#Couplings}&quot;">​</a></h2><p>A coupling mixes the strata after the kernel, <code>x_t = C_t (kernel ⋆ y)_t</code>.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Name</th><th style="text-align:right;">What it does</th><th style="text-align:right;">Returns</th></tr></thead><tbody><tr><td style="text-align:right;"><code>I</code>, <code>λI</code></td><td style="text-align:right;">no mixing, or a uniform scaling</td><td style="text-align:right;">–</td></tr><tr><td style="text-align:right;"><code>S × S</code> matrix (dense, <code>Diagonal</code>, sparse)</td><td style="text-align:right;">contact, mobility or type-to-type mixing</td><td style="text-align:right;">–</td></tr><tr><td style="text-align:right;"><code>TimeVarying(C)</code> with <code>C</code> <code>S × S × T</code></td><td style="text-align:right;">mixing that changes by day</td><td style="text-align:right;">–</td></tr><tr><td style="text-align:right;">your struct</td><td style="text-align:right;"><code>forward</code> on <code>Pressure()</code></td><td style="text-align:right;">–</td></tr></tbody></table><h2 id="Modifiers" tabindex="-1">Modifiers <a class="header-anchor" href="#Modifiers" aria-label="Permalink to &quot;Modifiers {#Modifiers}&quot;">​</a></h2><p>A modifier acts on <code>v_t = gain_t ⊙ x_t + add_t</code> after each recurrence step, in tuple order, with its own state.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Name</th><th style="text-align:right;">What it does</th><th style="text-align:right;">Recurrence</th><th style="text-align:right;">Convolution</th><th style="text-align:right;">Pointwise</th><th style="text-align:right;">Adjoint</th><th style="text-align:right;">Parameters</th></tr></thead><tbody><tr><td style="text-align:right;"><code>Depletion(N, form)</code></td><td style="text-align:right;">draws each step&#39;s values from a finite pool</td><td style="text-align:right;">yes</td><td style="text-align:right;">no</td><td style="text-align:right;">yes</td><td style="text-align:right;">hand-written</td><td style="text-align:right;"><code>N</code>, <code>heterogeneity</code>, <code>pool0</code></td></tr><tr><td style="text-align:right;"><code>Redistribute(K, ε)</code></td><td style="text-align:right;">moves a share <code>ε</code> of each stratum&#39;s value to others through <code>K</code></td><td style="text-align:right;">yes, with strata</td><td style="text-align:right;">no</td><td style="text-align:right;">no</td><td style="text-align:right;">hand-written</td><td style="text-align:right;"><code>ε</code></td></tr><tr><td style="text-align:right;"><code>Add(b)</code></td><td style="text-align:right;">adds <code>b</code> at this point in the modifier order</td><td style="text-align:right;">yes</td><td style="text-align:right;">no</td><td style="text-align:right;">yes</td><td style="text-align:right;">hand-written</td><td style="text-align:right;"><code>b</code></td></tr><tr><td style="text-align:right;"><code>Clamp(lo, hi)</code></td><td style="text-align:right;">bounds each value</td><td style="text-align:right;">yes</td><td style="text-align:right;">no</td><td style="text-align:right;">yes</td><td style="text-align:right;">hand-written</td><td style="text-align:right;"><code>lo</code>, <code>hi</code></td></tr></tbody></table><p>Every parameter is a scalar, <code>PerStratum(x)</code>, <code>TimeVarying(x)</code> or <code>TimeVarying(PerStratum(x))</code>. A bare array is an error that names the wrapper to use.</p><h2 id="Variants" tabindex="-1">Variants <a class="header-anchor" href="#Variants" aria-label="Permalink to &quot;Variants {#Variants}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Name</th><th style="text-align:right;">What it does</th><th style="text-align:right;">Example</th></tr></thead><tbody><tr><td style="text-align:right;"><code>Hazard()</code>, <code>Floor()</code></td><td style="text-align:right;">depletion forms</td><td style="text-align:right;"><code>Depletion(N)</code>, <code>Depletion(N, Floor())</code></td></tr><tr><td style="text-align:right;"><code>Primary()</code>, <code>Secondary()</code></td><td style="text-align:right;"><code>TimeVarying</code> indexing</td><td style="text-align:right;"><code>TimeVarying(P, Primary())</code></td></tr><tr><td style="text-align:right;">your struct</td><td style="text-align:right;">a new depletion form, with <code>forward</code> on <code>Step()</code></td><td style="text-align:right;"><code>Depletion(N, MyForm())</code></td></tr></tbody></table><h2 id="Extending" tabindex="-1">Extending <a class="header-anchor" href="#Extending" aria-label="Permalink to &quot;Extending {#Extending}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Name</th><th style="text-align:right;">What it does</th><th style="text-align:right;">Returns</th></tr></thead><tbody><tr><td style="text-align:right;"><code>forward(piece, role, args...)</code></td><td style="text-align:right;">the piece&#39;s maths for a role</td><td style="text-align:right;">writes in place, or returns scalars</td></tr><tr><td style="text-align:right;"><code>pullback!(grads, piece, role, args...)</code></td><td style="text-align:right;">its hand-written adjoint, optional</td><td style="text-align:right;">accumulates cotangents</td></tr><tr><td style="text-align:right;"><code>Run()</code>, <code>Step()</code>, <code>Init()</code>, <code>Pressure()</code></td><td style="text-align:right;">roles: an operator call, a modifier step, a modifier&#39;s initial state, a coupling&#39;s mixing</td><td style="text-align:right;">singletons</td></tr><tr><td style="text-align:right;"><code>ispointwise(m)</code></td><td style="text-align:right;">opts a modifier into the scalar <code>Step()</code> form</td><td style="text-align:right;"><code>Bool</code></td></tr><tr><td style="text-align:right;"><code>param_eltype(x)</code></td><td style="text-align:right;">the element type a piece&#39;s parameters promote the buffer to</td><td style="text-align:right;">a type</td></tr><tr><td style="text-align:right;"><code>PieceInterface</code></td><td style="text-align:right;">the Interfaces.jl conformance test for a new piece</td><td style="text-align:right;">a test result</td></tr></tbody></table><h2 id="Tooling" tabindex="-1">Tooling <a class="header-anchor" href="#Tooling" aria-label="Permalink to &quot;Tooling {#Tooling}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Name</th><th style="text-align:right;">What it does</th><th style="text-align:right;">Returns</th></tr></thead><tbody><tr><td style="text-align:right;"><code>NoAdjoint(op)</code></td><td style="text-align:right;">the same operator differentiated by plain AD, to compare against its adjoint</td><td style="text-align:right;">an operator</td></tr></tbody></table><h2 id="Concept-to-primitive" tabindex="-1">Concept to primitive <a class="header-anchor" href="#Concept-to-primitive" aria-label="Permalink to &quot;Concept to primitive {#Concept-to-primitive}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Concept</th><th style="text-align:right;">Primitive</th></tr></thead><tbody><tr><td style="text-align:right;">Renewal process</td><td style="text-align:right;"><code>Recurrence(gi)</code> with <code>R_t</code> as the gain</td></tr><tr><td style="text-align:right;">Susceptible depletion</td><td style="text-align:right;"><code>Depletion(N)</code> or <code>Depletion(N, Floor())</code></td></tr><tr><td style="text-align:right;">Imported cases</td><td style="text-align:right;"><code>add = ι</code> before the modifiers, or <code>Add(TimeVarying(ι))</code> at a place in their order</td></tr><tr><td style="text-align:right;">Random walk</td><td style="text-align:right;"><code>Recurrence([1.0])(; history = [z0], add = ϵ)</code></td></tr><tr><td style="text-align:right;">AR(p)</td><td style="text-align:right;"><code>Recurrence(ρ)</code> with the innovations as <code>add</code></td></tr><tr><td style="text-align:right;">Time-varying AR</td><td style="text-align:right;"><code>Recurrence(TimeVarying(ρ_t))</code></td></tr><tr><td style="text-align:right;">MA(q)</td><td style="text-align:right;"><code>Convolution(vcat(1, θ))</code></td></tr><tr><td style="text-align:right;">Reporting delay</td><td style="text-align:right;"><code>Convolution(pmf)</code></td></tr><tr><td style="text-align:right;">Delay that changes over time</td><td style="text-align:right;"><code>Convolution(TimeVarying(P))</code> or <code>TimeVarying(P, Primary())</code></td></tr><tr><td style="text-align:right;">Spatial or group mixing</td><td style="text-align:right;"><code>coupling = K</code> or <code>TimeVarying(K)</code></td></tr><tr><td style="text-align:right;">Per-group generation interval</td><td style="text-align:right;"><code>PerStratum(G)</code>, or <code>Pairwise(A)</code> per pair</td></tr><tr><td style="text-align:right;">Importation between patches</td><td style="text-align:right;"><code>Redistribute(K, ε)</code></td></tr><tr><td style="text-align:right;">Bed occupancy</td><td style="text-align:right;"><code>Convolution(survival)</code> or <code>Recurrence([1 - d])</code> with admissions as <code>add</code></td></tr><tr><td style="text-align:right;">Bed cap</td><td style="text-align:right;"><code>Clamp(0, beds)</code></td></tr><tr><td style="text-align:right;">Forecast from a fit</td><td style="text-align:right;"><code>with_state</code>, then <code>state =</code></td></tr><tr><td style="text-align:right;">Seed days returned first</td><td style="text-align:right;"><code>seeded</code></td></tr><tr><td style="text-align:right;">Intermediate quantities</td><td style="text-align:right;">recompute with <code>Convolution(vcat(0, g))</code> and array operations</td></tr></tbody></table>',27)])])}const x=e(a,[["render",o]]);export{y as __pageData,x as default};
